#!/bin/sh
set -eu
[ "$(cat /tmp/sysinfo/board_name)" = 'paiq-ec3-bt19d4l' ] || exit 0

# Migrate once; a later keep-settings upgrade must respect user changes.
if [ "$(uci -q get system.@system[0].hkc_paiq_defaults || true)" != '1' ]; then
	uci set system.@system[0].hostname='XXX'
	# Port topology and 192.168.2.1 are generated by board.d/config_generate.
	# I211 has two RX queues on this four-core CPU; use standard netifd RPS.
	uci set network.globals.packet_steering='1'
	uci commit network
	# Transparent SSR interception takes priority over flow-table bypass.
	uci set firewall.@defaults[0].flow_offloading='0'
	uci set firewall.@defaults[0].flow_offloading_hw='0'
	uci commit firewall
	uci set irqbalance.irqbalance.enabled='1'
	uci commit irqbalance
	uci set system.@system[0].hkc_paiq_defaults='1'
	uci commit system
fi

# Keep all SSR Plus settings and service behavior upstream. Only append the
# requested domains to the plugin's original blacklist.
forced_domains='/usr/share/hkc/forced-proxy-domains.list'
blacklist='/etc/ssrplus/black.list'
mkdir -p /etc/ssrplus
touch "$blacklist"
if [ ! -r "$forced_domains" ]; then
	echo "HKC firmware: forced proxy domain list is missing" >&2
	exit 1
fi

while IFS= read -r domain || [ -n "$domain" ]; do
	case "$domain" in
		''|'#'*) continue ;;
	esac
	grep -Fqx "$domain" "$blacklist" || printf '%s\n' "$domain" >>"$blacklist"
done <"$forced_domains"

exit 0
